package es.riegocerca.maps;
import android.app.Activity;import android.content.*;import android.net.Uri;import android.webkit.JavascriptInterface;import android.widget.Toast;
public class MapsBridge{private final Activity a;public MapsBridge(Activity a){this.a=a;}@JavascriptInterface public void navigate(double lat,double lon){a.runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse("google.navigation:q="+lat+","+lon+"&mode=d"));i.setPackage("com.google.android.apps.maps");try{a.startActivity(i);}catch(Exception e){a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.google.com/maps/dir/?api=1&destination="+lat+","+lon)));}});}}
